USE conectasucre_ddl;
SET @seed_day = CURRENT_DATE();
START TRANSACTION;

-- customers: 200 registros

-- producers: 30 registros

-- products: 100 registros

-- vehicles: 20 registros

-- drivers: 25 registros

-- routes: 15 registros

-- orders: 300 registros

-- order_details: 600 registros

-- dispatch_assignments: 250 registros

-- deliveries: 220 registros

-- incidents: 200 registros

COMMIT;

-- Verificacion de cantidades
SELECT 'customers' AS table_name, COUNT(*) AS total_records FROM customers
UNION ALL
SELECT 'producers' AS table_name, COUNT(*) AS total_records FROM producers
UNION ALL
SELECT 'products' AS table_name, COUNT(*) AS total_records FROM products
UNION ALL
SELECT 'vehicles' AS table_name, COUNT(*) AS total_records FROM vehicles
UNION ALL
SELECT 'drivers' AS table_name, COUNT(*) AS total_records FROM drivers
UNION ALL
SELECT 'routes' AS table_name, COUNT(*) AS total_records FROM routes
UNION ALL
SELECT 'orders' AS table_name, COUNT(*) AS total_records FROM orders
UNION ALL
SELECT 'order_details' AS table_name, COUNT(*) AS total_records FROM order_details
UNION ALL
SELECT 'dispatch_assignments' AS table_name, COUNT(*) AS total_records FROM dispatch_assignments
UNION ALL
SELECT 'deliveries' AS table_name, COUNT(*) AS total_records FROM deliveries
UNION ALL
SELECT 'incidents' AS table_name, COUNT(*) AS total_records FROM incidents
UNION ALL
SELECT 'dispatch_audits' AS table_name, COUNT(*) AS total_records FROM dispatch_audits;

-- Verificar consistencia de pesos (debe devolver cero filas).
SELECT o.order_id, o.total_weight_kg, SUM(od.quantity * od.unit_weight_kg) AS calculated_weight
FROM orders o JOIN order_details od ON od.order_id = o.order_id
GROUP BY o.order_id, o.total_weight_kg
HAVING o.total_weight_kg <> SUM(od.quantity * od.unit_weight_kg);

-- Verificar recursos activos duplicados (ambas consultas deben devolver cero filas).
SELECT vehicle_id, COUNT(*) AS active_dispatches FROM dispatch_assignments
WHERE dispatch_status IN ('ASSIGNED','IN_TRANSIT') GROUP BY vehicle_id HAVING COUNT(*) > 1;
SELECT driver_id, COUNT(*) AS active_dispatches FROM dispatch_assignments
WHERE dispatch_status IN ('ASSIGNED','IN_TRANSIT') GROUP BY driver_id HAVING COUNT(*) > 1;

-- Verificar sobrecarga de despachos (cero filas).
SELECT d.dispatch_id FROM dispatch_assignments d JOIN vehicles v ON v.vehicle_id=d.vehicle_id
WHERE d.loaded_weight_kg > v.load_capacity_kg;

-- Distribucion de estados para siguientes ejercicios.
SELECT order_status, COUNT(*) AS total FROM orders GROUP BY order_status;
SELECT dispatch_status, COUNT(*) AS total FROM dispatch_assignments GROUP BY dispatch_status;
SELECT delivery_status, COUNT(*) AS total FROM deliveries GROUP BY delivery_status;
